create table if not exists public.investment_suitability_profiles_v2 (id uuid primary key default gen_random_uuid(),investment_id uuid not null references public.investments(id) on delete cascade,model_version text not null,risk_band text not null,normalized_risk_score numeric(5,2) not null,growth_score numeric(5,2) not null,income_score numeric(5,2) not null,liquidity_score numeric(5,2) not null,diversification_score numeric(5,2) not null,minimum_horizon_months integer not null,drawdown_tolerance_required numeric(5,2) not null,volatility_tolerance_required numeric(5,2) not null,concentration_level text not null,geographic_scope text,currency_exposure text,suitability_summary text not null,key_fit_factors jsonb not null default '[]',key_mismatch_factors jsonb not null default '[]',source_basis jsonb not null default '{}',as_of_date date,created_at timestamptz default now(),updated_at timestamptz default now(),unique(investment_id,model_version)); create index if not exists isp2_inv_idx on public.investment_suitability_profiles_v2(investment_id); alter table public.investment_suitability_profiles_v2 enable row level security; create policy "public read active suitability profiles" on public.investment_suitability_profiles_v2 for select to anon,authenticated using (exists(select 1 from public.investments i where i.id=investment_id and i.data_status <> 'inactive'));
insert into public.investment_suitability_profiles_v2 (investment_id,model_version,risk_band,normalized_risk_score,growth_score,income_score,liquidity_score,diversification_score,minimum_horizon_months,drawdown_tolerance_required,volatility_tolerance_required,concentration_level,geographic_scope,currency_exposure,suitability_summary,key_fit_factors,key_mismatch_factors,source_basis,as_of_date)
select i.id,'suitability-v2.0',case when (p.target_allocation->>'equity')::numeric<=40 then 'Low' when (p.target_allocation->>'equity')::numeric<=60 then 'Medium' when (p.target_allocation->>'equity')::numeric<=80 then 'Medium-High' else 'High' end,(p.target_allocation->>'equity')::numeric,(p.target_allocation->>'equity')::numeric,case when (p.target_allocation->>'fixed_income')::numeric>=60 then 75 when (p.target_allocation->>'fixed_income')::numeric>=20 then 50 else 25 end,95,case when i.symbol in ('XIC','VCN','ZCN','ZSP','VFV','VUN','XUU') then 65 else 90 end,case when (p.target_allocation->>'equity')::numeric=100 then 60 when (p.target_allocation->>'equity')::numeric>=80 then 48 else 24 end,65,case when coalesce(r.volatility_1y_pct,0)>9 then 85 when coalesce(r.volatility_1y_pct,0)>7 then 65 when coalesce(r.volatility_1y_pct,0)>0 then 45 else (p.target_allocation->>'equity')::numeric end,case when (p.target_allocation->>'equity')::numeric>=80 then 'High' when (p.target_allocation->>'equity')::numeric>=40 then 'Moderate' else 'Low' end,case when i.symbol in ('XIC','VCN','ZCN') then 'Canada' when i.symbol in ('XUU','VUN','ZSP','VFV') then 'United States' else 'Global' end,coalesce(p.currency_hedging,'Varies by underlying exposure'),case when (p.target_allocation->>'equity')::numeric>=80 then 'Long-term growth profile with substantial equity-market risk.' when (p.target_allocation->>'equity')::numeric>=50 then 'Balanced core profile combining growth exposure with downside buffering.' else 'Stability and income-oriented profile with lower equity exposure.' end,'["Risk-band alignment","Asset-allocation fit","Diversification"]'::jsonb,'["Time horizon","Market drawdown risk","Liquidity needs"]'::jsonb,jsonb_build_object('profile_model',p.model_version,'risk_source',r.risk_level,'allocation',p.target_allocation,'ideal_for',p.ideal_for,'key_risks',p.key_risks),coalesce(p.as_of_date,current_date) from public.investments i join public.investment_profiles p on p.investment_id=i.id and p.model_version='profile-v1.0' left join public.investment_risk_metrics r on r.investment_id=i.id where i.data_status <> 'inactive' on conflict(investment_id,model_version) do update set risk_band=excluded.risk_band,normalized_risk_score=excluded.normalized_risk_score,growth_score=excluded.growth_score,income_score=excluded.income_score,liquidity_score=excluded.liquidity_score,diversification_score=excluded.diversification_score,minimum_horizon_months=excluded.minimum_horizon_months,drawdown_tolerance_required=excluded.drawdown_tolerance_required,volatility_tolerance_required=excluded.volatility_tolerance_required,concentration_level=excluded.concentration_level,geographic_scope=excluded.geographic_scope,currency_exposure=excluded.currency_exposure,suitability_summary=excluded.suitability_summary,key_fit_factors=excluded.key_fit_factors,key_mismatch_factors=excluded.key_mismatch_factors,source_basis=excluded.source_basis,as_of_date=excluded.as_of_date,updated_at=now();